dict(n=91397, t="Grammaire A1", s="Revisar presente, passé composé e futur proche", city="Genève", sc="classroom", rs="school",
 desc="O núcleo gramatical do A1 são três tempos: presente (je travaille), passé composé (j'ai mangé, nous sommes allés) e futur proche (je vais voyager). Dica: com verbos de movimento como «aller» o auxiliar é «être» e o particípio concorda; nunca diga «j'ai allé».",
 name="Léa", face="👩🏻", emo=["📘","🧠","⏳","✅"], mission="Hoje você revisa os três tempos do A1 numa conversa.",
 hook="Tu connais bien les trois temps ?|Você conhece bem os três tempos?", goal="Hier, j'ai mangé ; demain, je vais voyager",
 v=[("le présent","o presente","Soa como “le prê-ZÃ”.","📍"),("le passé composé","o passado composto","Soa como “le pa-SÊ côm-pô-ZÊ”.","⏪"),("le futur proche","o futuro próximo","Soa como “le fü-TÜR PROCH”.","⏩"),("hier","ontem","Soa como “iÉR”.","📆"),("un verbe","um verbo","Soa como “ẽ VÉRB”.","🔤"),("réviser","revisar","Soa como “rê-vi-ZÊ”.","📖")],
 chat=["P: Révisons les trois temps. D'abord le présent : que fais-tu maintenant ? | Vamos revisar os três tempos. Primeiro o presente: o que você faz agora?",
  "Y: Maintenant, je travaille à Genève et j'habite près du lac. | Agora, trabalho em Genebra e moro perto do lago.",
  "P: Très bien. Et hier, qu'est-ce que tu as fait ? | Muito bem. E ontem, o que você fez?",
  "Y: Hier, j'ai mangé une fondue avec des amis. | Ontem, comi uma fondue com amigos.",
  "P: Parfait ! « J'ai mangé », c'est le passé composé avec « avoir ». | Perfeito! «J'ai mangé» é o passé composé com «avoir».",
  "Y: Et avec « aller », qu'est-ce qu'on dit ? Hier soir, nous sommes allés au lac. | E com «aller», o que se diz? Ontem à noite, fomos ao lago.",
  "P: Avec « aller », on utilise « être » : « nous sommes allés ». | Com «aller», usa-se «être»: «nous sommes allés».",
  "Y: Et demain, je vais voyager à Zurich. | E amanhã, vou viajar para Zurique.",
  "P: Bravo, c'est le futur proche : « aller » plus l'infinitif. | Parabéns, é o futuro próximo: «aller» mais o infinitivo.",
  "Y: Donc : présent, passé composé, futur proche, c'est clair ! | Então: presente, passé composé, futur proche, está claro!",
  "P: Oui, tu as tout compris, bravo ! | Sim, você entendeu tudo, parabéns!"],
 tap=[("Qu'est-ce qu'il a mangé hier ?","O que ele comeu ontem?",["Une fondue","Une pizza","Un gâteau"],0,3,"Y: “j'ai mangé une fondue”"),
  ("Quel auxiliaire avec « aller » ?","Qual auxiliar com «aller»?",["Avoir","Être","Aller"],1,6,"P: “on utilise « être »”"),
  ("Que va-t-il faire demain ?","O que ele vai fazer amanhã?",["Travailler","Dormir","Voyager à Zurich"],2,7,"Y: “je vais voyager à Zurich”")],
 swap=("Três tempos: «Je mange», «J'ai mangé», «Je vais manger». 🎓 DELF A1: gramática em contexto.",
  [("Je mange…",[("Je mange","Como"),("J'ai mangé","Comi"),("Je vais manger","Vou comer")],[("une pizza","uma pizza"),("à midi","ao meio-dia"),("avec Léa","com a Léa")],"."),
   ("Je travaille…",[("Je travaille","Trabalho"),("J'ai travaillé","Trabalhei"),("Je vais travailler","Vou trabalhar")],[("ici","aqui"),("beaucoup","muito"),("avec Léa","com a Léa")],".")]),
 chat2=["Y: Léa, je peux te poser une question de grammaire ? | Léa, posso te fazer uma pergunta de gramática?",
  "P: Bien sûr, vas-y. | Claro, pode falar.",
  "Y: On dit « j'ai allé » ou « je suis allé » ? | Diz-se «j'ai allé» ou «je suis allé»?",
  "P: On dit « je suis allé » : c'est un verbe avec « être ». | Diz-se «je suis allé»: é um verbo com «être».",
  "Y: Merci ! Et « nous avons mangé », c'est correct ? | Obrigado! E «nous avons mangé», está correto?",
  "P: Oui, parfait : « manger » prend « avoir ». | Sim, perfeito: «manger» usa «avoir»."],
 slang=("Léa",["📘","#AE3EC9"],["F: T'as bûché la grammaire ce week-end ? | Você estudou duro a gramática no fim de semana?","Y: Oui grave, j'ai révisé tout le passé composé ! | Sim, demais, revisei todo o passé composé!","F: Chapeau ! Moi, je suis cuit, je comprends plus rien. | Parabéns! Eu estou ferrado, não entendo mais nada.","Y: Mais non, ça joue, on révise ensemble. | Que nada, tudo certo, revisamos juntos.","F: Ouais, t'es un crack, merci ! | É, você é um craque, valeu!","Y: Avec plaisir, après on se fait une fondue ! | Com prazer, depois a gente come uma fondue!"],
  {"bûché":"estudou muito, deu duro","grave":"demais, com certeza","je suis cuit":"estou ferrado","ça joue":"tudo certo, combinado","un crack":"um craque, um expert"},["je suis cuit","un crack"]),
 real=("Je ne suis pas allé au lac","Je suis pas allé au lac","na fala, o «ne» some: «je suis pas allé»"),
 recap_slang="un crack → um craque, um expert"),

